using System;using System.IO;using System.Net;using System.Linq;using System.Text;using System.Globalization;using System.Collections;using System.Collections.Generic;using System.Web.Script.Serialization;
public class SplitTraffic {public double DirectDown,DirectUp,ProxyDown,ProxyUp,Unknown;public bool Recorded;}
public sealed class ClashTrafficSource {
 class Connection {public double Down,Up;public string Kind;public DateTime Start;}
 readonly object gate=new object();readonly string keyPath;readonly Dictionary<string,Connection> previous=new Dictionary<string,Connection>();double oldDown,oldUp;bool ready;DateTime sampled;string previousAddress;public string Status="尚未启用直连/代理统计";
 public ClashTrafficSource(string folder){keyPath=Path.Combine(folder,"clash-history-key.dat");}
 public static Uri Address(string value){Uri uri;IPAddress ip;if(!Uri.TryCreate(value,UriKind.Absolute,out uri)||uri.Scheme!="http"||!IPAddress.TryParse(uri.Host.Trim('[',']'),out ip)||!IPAddress.IsLoopback(ip)||!String.IsNullOrEmpty(uri.UserInfo)||uri.AbsolutePath!="/"||!String.IsNullOrEmpty(uri.Query)||!String.IsNullOrEmpty(uri.Fragment))throw new ArgumentException("仅支持本机控制地址，例如 http://127.0.0.1:9090；不会连接远程服务器。");return uri;}
 public void SaveKey(string address,string secret){Address(address);if(secret.Length>1024||secret.Any(Char.IsControl))throw new ArgumentException("控制密钥格式无效。");Directory.CreateDirectory(Path.GetDirectoryName(keyPath));string temp=keyPath+".tmp";File.WriteAllBytes(temp,LocalProtection.Protect(Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(new Dictionary<string,string>{{"address",address},{"secret",secret}}))));if(File.Exists(keyPath))File.Replace(temp,keyPath,null);else File.Move(temp,keyPath);Reset();}
 string Key(string address){if(!File.Exists(keyPath))return "";var data=new JavaScriptSerializer().Deserialize<Dictionary<string,string>>(Encoding.UTF8.GetString(LocalProtection.Unprotect(File.ReadAllBytes(keyPath))));return data!=null&&data.ContainsKey("address")&&data["address"]==address&&data.ContainsKey("secret")?(data["secret"]??""):"";}
 public SplitTraffic Fetch(string address,DateTime now){lock(gate)return FetchCore(address,now);}
 SplitTraffic FetchCore(string address,DateTime now){try{var uri=Address(address);if(previousAddress!=address){Reset();previousAddress=address;}var request=(HttpWebRequest)WebRequest.Create(new Uri(uri,"connections"));request.Method="GET";request.Proxy=null;request.AllowAutoRedirect=false;request.Timeout=request.ReadWriteTimeout=1800;string secret=Key(address);if(secret.Length>0)request.Headers["Authorization"]="Bearer "+secret;using(var response=(HttpWebResponse)request.GetResponse()){if(response.StatusCode!=HttpStatusCode.OK)throw new IOException("控制接口未返回统计");using(var reader=new StreamReader(response.GetResponseStream())){var text=new StringBuilder();var buffer=new char[4096];int n;while((n=reader.Read(buffer,0,buffer.Length))>0){text.Append(buffer,0,n);if(text.Length>8388608)throw new IOException("连接统计过大");}var result=Parse(text.ToString(),now);Status=result.Recorded?"直连/代理采样已连接 · 短连接差额列为未分类":"已连接 · 正在建立计数基线";return result;}}}catch(Exception e){if(!(e is WebException)&&!(e is IOException)&&!(e is ArgumentException)&&!(e is InvalidOperationException)&&!(e is System.Security.Cryptography.CryptographicException))throw;Reset();Status=e is WebException?"控制接口不可用或未授权，请检查地址与密钥":"控制统计未就绪，保留已有历史";return new SplitTraffic();}}
 public void Reset(){lock(gate){ready=false;previous.Clear();}}
 static double Num(Dictionary<string,object> d,string k){object v;double n;return d.TryGetValue(k,out v)&&Double.TryParse(Convert.ToString(v,CultureInfo.InvariantCulture),NumberStyles.Float,CultureInfo.InvariantCulture,out n)&&!Double.IsNaN(n)&&!Double.IsInfinity(n)&&n>=0?n:0;}
 public SplitTraffic Parse(string text,DateTime now){lock(gate)return ParseCore(text,now);}
 SplitTraffic ParseCore(string text,DateTime now){var data=new JavaScriptSerializer{MaxJsonLength=8388608}.Deserialize<Dictionary<string,object>>(text);object value;if(data==null||!data.ContainsKey("downloadTotal")||!data.ContainsKey("uploadTotal")||!data.TryGetValue("connections",out value)||!(value is IEnumerable))throw new ArgumentException("缺少连接统计");var current=new Dictionary<string,Connection>();foreach(object o in (IEnumerable)value){var c=o as Dictionary<string,object>;object id,chains,start;if(c==null||!c.TryGetValue("id",out id)||!(id is string)||((string)id).Length>128)continue;var names=c.TryGetValue("chains",out chains)&&chains is IEnumerable?((IEnumerable)chains).Cast<object>().Select(Convert.ToString).Where(x=>!String.IsNullOrEmpty(x)).ToArray():new string[0];DateTime started;DateTime.TryParse(c.TryGetValue("start",out start)?Convert.ToString(start):"",CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out started);current[(string)id]=new Connection{Down=Num(c,"download"),Up=Num(c,"upload"),Start=started.ToUniversalTime(),Kind=names.Any(x=>x.Equals("DIRECT",StringComparison.OrdinalIgnoreCase))?"direct":names.Length>0&&!names.Any(x=>x.Equals("REJECT",StringComparison.OrdinalIgnoreCase))?"proxy":"unknown"};}double down=Num(data,"downloadTotal"),up=Num(data,"uploadTotal");var result=new SplitTraffic();double seconds=(now-sampled).TotalSeconds;if(ready&&seconds>0&&seconds<=10&&down>=oldDown&&up>=oldUp){result.Recorded=true;foreach(var pair in current){Connection old;bool known=previous.TryGetValue(pair.Key,out old);var c=pair.Value;if(!known&&c.Start<sampled)continue;double d=known?Math.Max(0,c.Down-old.Down):c.Down,u=known?Math.Max(0,c.Up-old.Up):c.Up;if(c.Kind=="direct"){result.DirectDown+=d;result.DirectUp+=u;}else if(c.Kind=="proxy"){result.ProxyDown+=d;result.ProxyUp+=u;}}double totalDown=down-oldDown,totalUp=up-oldUp;if(result.DirectDown+result.ProxyDown>totalDown||result.DirectUp+result.ProxyUp>totalUp){result.DirectDown=result.DirectUp=result.ProxyDown=result.ProxyUp=0;}result.Unknown=Math.Max(0,totalDown+totalUp-result.DirectDown-result.DirectUp-result.ProxyDown-result.ProxyUp);}previous.Clear();foreach(var p in current)previous[p.Key]=p.Value;ready=true;sampled=now;oldDown=down;oldUp=up;return result;}
}
